grid=[[1]*22 for _ in range(12)]
zeros={
1:[1,2,3,5,7,8,9,12],
2:[1],3:[1],4:[1,12],7:[1],8:[12],9:[1],10:[1,12],11:[1,2,5,6,7,8,9,11,12]}
for r,cs in zeros.items():
 for c in cs:grid[r][c]=0
# fill horizontal intervals between zero markers
for r in range(12):
 cs=[c for c,x in enumerate(grid[r]) if x==0]
 if len(cs)>1:
  for c in range(min(cs),max(cs)+1):
   if grid[r][c]==1:grid[r][c]=2
# fill vertical intervals using marker rows (grid zeros unchanged)
for c in range(22):
 rs=[r for r in range(12) if grid[r][c]==0]
 if len(rs)>1:
  for r in range(min(rs),max(rs)+1):
   if grid[r][c]==1:grid[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in grid))
